-- hash.lua: the one hash convention of the UI restyle programme. build.py inlines this file; do not copy it.
-- Both hashes run over the raw source BYTES and stay exact in Luau doubles.
--   djb2     x = (x * 33 + byte) % 2^32, seed 5381 (same as scripts/hover_feel and classic/manifest.json "djb2")
--   fnv1a32  FNV-1a 32, seed 2166136261, prime 16777619 (classic/manifest.json "fnv1a32").
--            f * 16777619 = f * 2^24 + f * 403; lshift keeps the first term under 2^32.
-- A fingerprint is "<djb2>-<fnv1a32>-<byte length>" in decimal. Python mirror: plan.py fingerprint().
local Hash = {}
function Hash.pair(s)
	local d = 5381
	local f = 2166136261
	for i = 1, #s do
		local b = string.byte(s, i)
		d = (d * 33 + b) % 4294967296
		f = bit32.bxor(f, b)
		f = (bit32.lshift(f, 24) + f * 403) % 4294967296
	end
	return d, f
end
function Hash.fingerprint(s)
	local d, f = Hash.pair(s)
	return string.format("%d-%d-%d", d, f, #s)
end
-- plan.lua: decision logic of the UI restyle installer engine. Pure: no instances, no services.
-- Line-for-line mirror of plan.py (read its header for the data shapes). selftest.lua replays vectors made by
-- plan.py against this file, so change both together.
local Plan = {}
Plan.TRANSACTIONS = { "hierarchy", "sources" }
local HIERARCHY_KINDS = { create = true, attribute = true, property = true }
local MODES = { AUDIT = true, APPLY = true, ROLLBACK = true }

local function contains(list, value)
	for _, item in ipairs(list or {}) do
		if item == value then
			return true
		end
	end
	return false
end

function Plan.transactionOf(op)
	if op.kind == "source" then
		return "sources"
	end
	if HIERARCHY_KINDS[op.kind] then
		return "hierarchy"
	end
	return ""
end

-- -> state, reason. parentState is the state of the create op that makes this op's parent, or "".
function Plan.classify(op, obs, parentState)
	if obs.ambiguous then
		return "blocked", "ambiguous path: two instances share a name"
	end
	local kind = op.kind
	if kind == "source" then
		if not obs.exists then
			return "blocked", "script is missing"
		end
		if obs.className ~= op.class then
			return "blocked", "class is " .. tostring(obs.className) .. ", expected " .. tostring(op.class)
		end
		if obs.fp == op.after then
			return "after", ""
		end
		if obs.fp == op.before then
			return "before", ""
		end
		if contains(op.prior, obs.fp) then
			return "prior", ""
		end
		return "blocked", "source matches no recorded hash (" .. tostring(obs.fp) .. ")"
	end
	if kind == "create" then
		if not obs.exists then
			if obs.parentExists or parentState == "before" then
				return "before", ""
			end
			return "blocked", "parent is missing"
		end
		if obs.className ~= op.class then
			return "blocked", "exists as " .. tostring(obs.className) .. ", expected " .. tostring(op.class)
		end
		if obs.mark ~= op.mark then
			return "blocked", "exists and was not created by this installer (install mark absent or different)"
		end
		if op.after == nil then
			return "after", ""
		end
		if obs.fp == op.after then
			return "after", ""
		end
		if contains(op.prior, obs.fp) then
			return "prior", ""
		end
		return "blocked", "created script was edited since install (" .. tostring(obs.fp) .. ")"
	end
	if kind == "attribute" or kind == "property" then
		if not obs.exists then
			return "blocked", "target instance is missing"
		end
		local match = obs.match
		if match == "after" or match == "before" or match == "prior" then
			return match, ""
		end
		return "blocked", "value was edited since it was recorded"
	end
	return "blocked", "unknown op kind"
end

-- Why ROLLBACK must refuse this op even though its state is known, or "".
function Plan.rollbackBlock(op, obs, state)
	if op.kind == "create" and (state == "after" or state == "prior") then
		local foreign = obs.foreignChildren or {}
		if #foreign > 0 then
			return "has children this installer did not create: " .. table.concat(foreign, ", ")
		end
	end
	return ""
end

-- -> { [id] = { state, reason, rollback } }. A create op's parent op always comes earlier in ops.
function Plan.classifyAll(ops, observations)
	local results = {}
	for _, op in ipairs(ops) do
		local obs = observations[op.id]
		local parent = results[op.parentOp or ""]
		local parentState = ""
		if parent then
			parentState = parent.state
		end
		local state, reason = Plan.classify(op, obs, parentState)
		results[op.id] = { state = state, reason = reason, rollback = Plan.rollbackBlock(op, obs, state) }
	end
	return results
end

function Plan.transactionState(name, ops, results)
	local count, blocked, after, before = 0, 0, 0, 0
	for _, op in ipairs(ops) do
		if Plan.transactionOf(op) == name then
			local state = results[op.id].state
			count += 1
			if state == "blocked" then
				blocked += 1
			elseif state == "after" then
				after += 1
			elseif state == "before" then
				before += 1
			end
		end
	end
	if count == 0 then
		return "empty"
	end
	if blocked > 0 then
		return "blocked"
	end
	if after == count then
		return "after"
	end
	if before == count then
		return "before"
	end
	return "mixed"
end

function Plan.actionFor(mode, op, state)
	local kind = op.kind
	if mode == "APPLY" then
		if kind == "source" then
			return "write"
		end
		if kind == "create" then
			if state == "before" then
				return "create"
			end
			return "rewrite"
		end
		return "set"
	end
	if kind == "source" then
		return "restore"
	end
	if kind == "create" then
		return "remove"
	end
	return "reset"
end

-- One run writes at most ONE transaction.
-- APPLY order: hierarchy, then sources. ROLLBACK order: sources, then hierarchy (ops in reverse).
-- gate: placeOk, isEdit, testWindow ("" or why the sandbox test window counts as open), notInstallable.
-- -> { blockers = {...}, states = { [name] = state }, transaction = name or "", actions = { { id, action } }, write }
function Plan.decide(mode, ops, results, gate)
	local blockers = {}
	local held = {}
	if not MODES[mode] then
		table.insert(blockers, "unknown mode " .. tostring(mode))
	end
	if not gate.placeOk then
		table.insert(blockers, "wrong place")
	end
	if not gate.isEdit then
		table.insert(blockers, "Studio is not in Edit mode")
	end
	if mode ~= "AUDIT" and gate.notInstallable then
		table.insert(blockers, "this phase is marked not installable")
	end
	if mode == "APPLY" and (gate.testWindow or "") ~= "" then
		table.insert(blockers, "sandbox test window is open: " .. gate.testWindow)
	end
	for _, op in ipairs(ops) do
		local txn = Plan.transactionOf(op)
		if txn == "" or (op.transaction or txn) ~= txn then
			table.insert(blockers, op.id .. ": refusing to mix transactions (" .. tostring(op.kind) .. " op declared in " .. tostring(op.transaction or "?") .. ")")
		end
		local result = results[op.id]
		if result.state == "blocked" then
			table.insert(blockers, op.id .. ": " .. result.reason)
		elseif mode == "ROLLBACK" and result.rollback ~= "" then
			-- Held until the transaction is known: a create op's children only matter when this run removes it.
			table.insert(held, { txn = txn, text = op.id .. ": " .. result.rollback })
		end
	end
	local states = {}
	for _, name in ipairs(Plan.TRANSACTIONS) do
		states[name] = Plan.transactionState(name, ops, results)
	end
	local want = "after"
	local order, ordered = {}, {}
	if mode == "ROLLBACK" then
		want = "before"
		for i = #Plan.TRANSACTIONS, 1, -1 do
			table.insert(order, Plan.TRANSACTIONS[i])
		end
		for i = #ops, 1, -1 do
			table.insert(ordered, ops[i])
		end
	else
		for _, name in ipairs(Plan.TRANSACTIONS) do
			table.insert(order, name)
		end
		for _, op in ipairs(ops) do
			table.insert(ordered, op)
		end
	end
	local transaction, actions = "", {}
	if mode == "APPLY" or mode == "ROLLBACK" then
		for _, name in ipairs(order) do
			local pending = 0
			for _, op in ipairs(ordered) do
				local state = results[op.id].state
				if Plan.transactionOf(op) == name and state ~= want then
					pending += 1
					if state ~= "blocked" then
						table.insert(actions, { id = op.id, action = Plan.actionFor(mode, op, state) })
					end
				end
			end
			if pending > 0 then
				transaction = name
				break
			end
		end
	end
	for _, item in ipairs(held) do
		if item.txn == transaction then
			table.insert(blockers, item.text)
		end
	end
	return { blockers = blockers, states = states, transaction = transaction, actions = actions, write = #blockers == 0 and #actions > 0 }
end
-- engine.lua: the one installer engine of the UI restyle programme. Needs Hash (hash.lua) and Plan (plan.lua)
-- above it; build.py concatenates them. Engine.run(MODE, DATA, env) -> report table.
--
-- Everything the engine touches outside its own logic comes through env, so selftest.lua can run it against a
-- detached tree with fake files:
--   env.placeId, env.isEdit           where it is running
--   env.root(name) -> Instance?       resolves the first path element (a service in the real place)
--   env.fetch(file) -> string         repository file by path; errors when it cannot be read
--   env.loadChunk(text, name)         -> function | false, syntax error | nil, why no check is possible
--   env.getSource(node) / env.setSource(node, text)    direct .Source, as the lighting and hover_feel engines do
--   env.wait()                        task.wait between batches
--   env.waypoint(label)               ChangeHistoryService:SetWaypoint, as hover_feel does
--   env.jsonDecode(text)              only for the Classic verify result
--
-- Guarantees (decision rules are in plan.lua):
--   * Nothing is written unless the place and Edit mode are right, every op is in a known state, and every source
--     that will be written was fetched, matched its recorded fingerprint and compiled.
--   * One run writes one transaction: hierarchy (create, attribute, property) or sources. Never both.
--   * A failed write undoes every change of the run, in reverse order.
local Engine = {}
Engine.VERSION = 1
Engine.TEST_WINDOW_PATH = { "ReplicatedStorage", "Config", "Player", "Onboarding" }
local BATCH = 20

local function decode(value)
	if type(value) ~= "table" then
		return value
	end
	local kind = value.Type
	if kind == "Color3" then
		return Color3.new(value.R, value.G, value.B)
	end
	if kind == "Vector3" then
		return Vector3.new(value.X, value.Y, value.Z)
	end
	if kind == "Vector2" then
		return Vector2.new(value.X, value.Y)
	end
	if kind == "UDim" then
		return UDim.new(value.Scale, value.Offset)
	end
	if kind == "UDim2" then
		return UDim2.new(value.XScale, value.XOffset, value.YScale, value.YOffset)
	end
	error("unsupported value type " .. tostring(kind))
end

local function equal(a, b)
	if type(a) == "number" and type(b) == "number" then
		return a == b or math.abs(a - b) <= 1e-6 * math.max(1, math.abs(a), math.abs(b))
	end
	return typeof(a) == typeof(b) and a == b
end

local function matchOf(op, value)
	if equal(value, decode(op.after)) then
		return "after"
	end
	if equal(value, decode(op.before)) then
		return "before"
	end
	for _, was in ipairs(op.was or {}) do
		if equal(value, decode(was)) then
			return "prior"
		end
	end
	return "other"
end

-- Syntax check through loadstring. Edit has it; Play does not, and then the check is reported as not done.
function Engine.loadChunk(text, name)
	if type(loadstring) ~= "function" then
		return nil, "loadstring is unavailable"
	end
	local ok, chunk, err = pcall(loadstring, text, "=" .. tostring(name))
	if not ok then
		return nil, "loadstring is unavailable: " .. tostring(chunk)
	end
	if chunk == nil then
		return false, tostring(err)
	end
	return chunk
end

-- AUDIT hook: runs scripts/ui_restyle/classic/out_verify_classic.lua (read-only, returns one JSON string).
function Engine.classicVerify(file, env)
	local fetched, text = pcall(env.fetch, file)
	if not fetched or type(text) ~= "string" then
		return { ran = false, ok = false, error = "could not fetch " .. file .. ": " .. tostring(text) }
	end
	local chunk, err = env.loadChunk(text, "out_verify_classic")
	if not chunk then
		return { ran = false, ok = false, error = "could not load " .. file .. ": " .. tostring(err) }
	end
	local ran, result = pcall(chunk)
	if not ran then
		return { ran = false, ok = false, error = tostring(result) }
	end
	local decoded = result
	if type(result) == "string" and env.jsonDecode then
		local parsed, value = pcall(env.jsonDecode, result)
		if parsed then
			decoded = value
		end
	end
	if type(decoded) == "table" then
		return { ran = true, ok = decoded.ok == true, failures = decoded.failures, result = decoded }
	end
	return { ran = true, ok = false, error = "unexpected result", result = tostring(result) }
end

function Engine.run(MODE, DATA, env)
	local MARK = DATA.markAttribute
	local ops = DATA.ops
	local report = {
		engine = Engine.VERSION, phase = DATA.phase, mode = MODE, ok = false, wrote = 0, transaction = "",
		blockers = {}, warnings = {}, transactions = {}, next = "",
	}
	local function blocker(text)
		table.insert(report.blockers, text)
	end
	local function warning(text)
		table.insert(report.warnings, text)
	end
	local byId, marks = {}, {}
	for _, op in ipairs(ops) do
		byId[op.id] = op
		if op.mark then
			marks[op.mark] = true
		end
	end

	local function childNamed(parent, name)
		local found, count = nil, 0
		for _, child in ipairs(parent:GetChildren()) do
			if child.Name == name then
				found = found or child
				count += 1
			end
		end
		return found, count
	end
	-- Walks path[1..last]. -> instance, "ok" | nil, "missing" | nil, "ambiguous"
	local function resolve(path, last)
		local node = env.root(path[1])
		if not node then
			return nil, "missing"
		end
		for i = 2, last do
			local child, count = childNamed(node, path[i])
			if count > 1 then
				return nil, "ambiguous"
			end
			if not child then
				return nil, "missing"
			end
			node = child
		end
		return node, "ok"
	end

	-- -> observation (plan.py header), instance, parent (create only), raw value (attribute and property only)
	local function observe(op)
		local obs = {}
		if op.kind == "create" then
			local parent, status = resolve(op.path, #op.path - 1)
			if status == "ambiguous" then
				obs.ambiguous = true
				return obs
			end
			obs.parentExists = parent ~= nil
			obs.exists = false
			if not parent then
				return obs
			end
			local node, count = childNamed(parent, op.path[#op.path])
			if count > 1 then
				obs.ambiguous = true
				return obs
			end
			if not node then
				return obs, nil, parent
			end
			obs.exists = true
			obs.className = node.ClassName
			local mark = node:GetAttribute(MARK)
			if type(mark) == "string" then
				obs.mark = mark
			end
			if op.after ~= nil and node:IsA("LuaSourceContainer") then
				obs.fp = Hash.fingerprint(env.getSource(node))
			end
			obs.foreignChildren = {}
			for _, child in ipairs(node:GetChildren()) do
				local childMark = child:GetAttribute(MARK)
				if type(childMark) ~= "string" or not marks[childMark] then
					table.insert(obs.foreignChildren, child.Name)
				end
			end
			table.sort(obs.foreignChildren)
			local tuned = {}
			for key, value in pairs(op.attributes or {}) do
				if not equal(node:GetAttribute(key), decode(value)) then
					table.insert(tuned, key)
				end
			end
			table.sort(tuned)
			obs.tuned = table.concat(tuned, ", ")
			return obs, node, parent
		end
		local node, status = resolve(op.path, #op.path)
		if status == "ambiguous" then
			obs.ambiguous = true
			return obs
		end
		obs.exists = node ~= nil
		if not node then
			return obs
		end
		obs.className = node.ClassName
		if op.kind == "source" then
			if node:IsA("LuaSourceContainer") then
				obs.fp = Hash.fingerprint(env.getSource(node))
			end
			return obs, node
		end
		local value
		if op.kind == "attribute" then
			value = node:GetAttribute(op.key)
		else
			local readable, read = pcall(function()
				return node[op.key]
			end)
			if not readable then
				obs.match = "other"
				obs.now = "unreadable property"
				return obs, node
			end
			value = read
		end
		obs.match = matchOf(op, value)
		obs.now = tostring(value)
		return obs, node, nil, value
	end
	local function observeAll()
		local observations, raw = {}, {}
		for _, op in ipairs(ops) do
			local obs, _, _, value = observe(op)
			observations[op.id] = obs
			raw[op.id] = value
		end
		return observations, raw
	end

	-- "" when closed. APPLY refuses while the sandbox test window is open (or cannot be checked).
	local function testWindow()
		local folder = resolve(Engine.TEST_WINDOW_PATH, #Engine.TEST_WINDOW_PATH)
		if not folder then
			return table.concat(Engine.TEST_WINDOW_PATH, ".") .. " was not found, so the window cannot be checked"
		end
		if folder:GetAttribute("StudioVehicleSandboxEveryPlay") == true then
			return "StudioVehicleSandboxEveryPlay is true"
		end
		if folder:GetAttribute("UIRestyleTestWindow") ~= nil then
			return "UIRestyleTestWindow marker is set"
		end
		return ""
	end

	local served, texts = {}, {}
	-- Fetch, fingerprint and compile one recorded source. which = "after" | "before".
	-- -> text or nil, "ok" | "unchecked" | "unavailable" | "mismatch" | "syntax", detail
	local function load(op, which)
		local fetched, text = pcall(env.fetch, DATA.base .. op.file[which])
		if not fetched or type(text) ~= "string" then
			return nil, "unavailable", tostring(text)
		end
		if Hash.fingerprint(text) ~= op[which] then
			return nil, "mismatch", ""
		end
		local chunk, err = env.loadChunk(text, op.id)
		if chunk == false then
			return nil, "syntax", tostring(err)
		end
		if chunk == nil then
			return text, "unchecked", tostring(err)
		end
		return text, "ok", ""
	end

	local function fill(results, observations, states)
		report.transactions = {}
		for _, name in ipairs(Plan.TRANSACTIONS) do
			report.transactions[name] = { state = states[name], ops = {} }
		end
		for _, op in ipairs(ops) do
			local result, obs = results[op.id], observations[op.id]
			local bucket = report.transactions[Plan.transactionOf(op)] or report.transactions.hierarchy
			local state = result.state
			if state == "blocked" then
				state = "BLOCKED"
			end
			table.insert(bucket.ops, {
				id = op.id, kind = op.kind, path = table.concat(op.path, "."), key = op.key or "",
				state = state, reason = result.reason, rollback = result.rollback,
				served = served[op.id] or "", now = obs.now or obs.fp or "", tuned = obs.tuned or "",
			})
		end
	end
	local function preview(decision)
		return { transaction = decision.transaction, ops = #decision.actions, blockers = decision.blockers }
	end

	local observations, raw = observeAll()
	local results = Plan.classifyAll(ops, observations)
	local gate = {
		placeOk = env.placeId == DATA.placeId,
		isEdit = env.isEdit == true,
		testWindow = testWindow(),
		notInstallable = DATA.installable == false,
	}

	if MODE == "AUDIT" then
		local decision = Plan.decide("AUDIT", ops, results, gate)
		for _, text in ipairs(decision.blockers) do
			blocker(text)
		end
		for _, op in ipairs(ops) do
			local state = results[op.id].state
			if op.file and op.file.after and state ~= "after" and state ~= "blocked" then
				local _, status, detail = load(op, "after")
				served[op.id] = status
				if status == "mismatch" then
					blocker(op.id .. ": the served after-source does not match its recorded hash")
				elseif status == "syntax" then
					blocker(op.id .. ": the after-source does not compile: " .. detail)
				elseif status == "unavailable" then
					warning(op.id .. ": the after-source could not be fetched (" .. detail .. ")")
				elseif status == "unchecked" then
					warning(op.id .. ": syntax not checked (" .. detail .. ")")
				end
			end
		end
		local apply = Plan.decide("APPLY", ops, results, gate)
		local rollback = Plan.decide("ROLLBACK", ops, results, gate)
		report.apply = preview(apply)
		report.rollback = preview(rollback)
		if gate.testWindow ~= "" then
			warning("APPLY would refuse: sandbox test window is open: " .. gate.testWindow)
		end
		if DATA.classicVerify then
			local classic = Engine.classicVerify(DATA.classicVerify, env)
			report.classicVerify = classic
			if not classic.ran then
				warning("Classic verify did not run: " .. tostring(classic.error))
			elseif not classic.ok then
				blocker("Classic verify reports failures: " .. tostring(classic.failures))
			end
		end
		fill(results, observations, decision.states)
		report.ok = #report.blockers == 0
		if apply.transaction ~= "" then
			report.next = "APPLY would write the " .. apply.transaction .. " transaction (" .. #apply.actions .. " ops)."
		else
			report.next = "APPLY has nothing to write."
		end
		return report
	end

	local decision = Plan.decide(MODE, ops, results, gate)
	for _, text in ipairs(decision.blockers) do
		blocker(text)
	end
	report.transaction = decision.transaction
	local want, which = "after", "after"
	if MODE == "ROLLBACK" then
		want, which = "before", "before"
	end
	if decision.write then
		for _, item in ipairs(decision.actions) do
			local op = byId[item.id]
			local action = item.action
			if action == "write" or action == "rewrite" or action == "restore" or (action == "create" and op.after ~= nil) then
				local text, status, detail = load(op, which)
				served[op.id] = status
				if text == nil then
					blocker(op.id .. ": the " .. which .. "-source is " .. status .. " " .. detail)
				else
					texts[op.id] = text
					if status == "unchecked" then
						warning(op.id .. ": syntax not checked (" .. detail .. ")")
					end
				end
			end
		end
		if #report.blockers == 0 then
			-- Fetching yields, so read the place again and require that nothing moved.
			local observationsNow, rawNow = observeAll()
			local resultsNow = Plan.classifyAll(ops, observationsNow)
			for _, op in ipairs(ops) do
				if resultsNow[op.id].state ~= results[op.id].state or observationsNow[op.id].fp ~= observations[op.id].fp then
					blocker(op.id .. ": changed while sources were being fetched")
				end
			end
			observations, raw, results = observationsNow, rawNow, resultsNow
		end
	end
	if #report.blockers > 0 or not decision.write then
		fill(results, observations, decision.states)
		report.ok = #report.blockers == 0
		if report.ok then
			report.next = "Nothing to write: every op is already " .. want .. "."
		else
			report.next = "Blocked. Nothing was written."
		end
		return report
	end

	local journal, removed = {}, {}
	local function perform(op, action)
		if Plan.transactionOf(op) ~= decision.transaction then
			error(op.id .. ": refusing to mix transactions")
		end
		local obs, node, parent, value = observe(op)
		local target = op.after
		if MODE == "ROLLBACK" then
			target = op.before
		end
		if action == "create" then
			if obs.exists or parent == nil then
				error(op.id .. ": target changed during the run")
			end
			local made = Instance.new(op.class)
			table.insert(journal, function()
				made:Destroy()
			end)
			made.Name = op.path[#op.path]
			if op.after ~= nil then
				env.setSource(made, texts[op.id])
			end
			for key, propertyValue in pairs(op.properties or {}) do
				made[key] = decode(propertyValue)
			end
			for key, attributeValue in pairs(op.attributes or {}) do
				made:SetAttribute(key, decode(attributeValue))
			end
			made:SetAttribute(MARK, op.mark)
			made.Parent = parent
		elseif node == nil then
			error(op.id .. ": target disappeared during the run")
		elseif action == "write" or action == "rewrite" or action == "restore" then
			local old = env.getSource(node)
			if Hash.fingerprint(old) ~= observations[op.id].fp then
				error(op.id .. ": source changed during the run")
			end
			table.insert(journal, function()
				env.setSource(node, old)
			end)
			env.setSource(node, texts[op.id])
		elseif action == "remove" then
			local was = node.Parent
			table.insert(journal, function()
				node.Parent = was
			end)
			table.insert(removed, node)
			node.Parent = nil
		elseif op.kind == "attribute" then
			if not equal(value, raw[op.id]) then
				error(op.id .. ": value changed during the run")
			end
			table.insert(journal, function()
				node:SetAttribute(op.key, value)
			end)
			node:SetAttribute(op.key, decode(target))
		elseif op.kind == "property" then
			table.insert(journal, function()
				node[op.key] = value
			end)
			node[op.key] = decode(target)
		else
			error(op.id .. ": unknown action " .. tostring(action))
		end
	end

	local label = "ui_restyle " .. tostring(DATA.phase) .. " " .. MODE .. " " .. decision.transaction
	if not pcall(env.waypoint, label .. " before") then
		warning("ChangeHistoryService waypoint failed (before)")
	end
	local wrote = 0
	local ok, problem = pcall(function()
		for index, item in ipairs(decision.actions) do
			local op = byId[item.id]
			perform(op, item.action)
			wrote += 1
			if op.kind == "source" or index % BATCH == 0 then
				env.wait()
			end
		end
		local check = Plan.classifyAll(ops, (observeAll()))
		for _, op in ipairs(ops) do
			if Plan.transactionOf(op) == decision.transaction and check[op.id].state ~= want then
				error(op.id .. ": post-write check found " .. check[op.id].state .. " " .. check[op.id].reason)
			end
		end
	end)
	if ok then
		-- Removed instances were only unparented until the whole transaction verified.
		for _, node in ipairs(removed) do
			pcall(function()
				node:Destroy()
			end)
		end
		report.wrote = wrote
		if not pcall(env.waypoint, label .. " after") then
			warning("ChangeHistoryService waypoint failed (after)")
		end
	else
		local errors = {}
		for i = #journal, 1, -1 do
			local undone, err = pcall(journal[i])
			if not undone then
				table.insert(errors, tostring(err))
			end
		end
		report.restored = #errors == 0
		if #errors == 0 then
			blocker("write failed and every change of this run was undone: " .. tostring(problem))
		else
			blocker("write failed and RECOVERY IS INCOMPLETE (" .. table.concat(errors, "; ") .. "): " .. tostring(problem))
		end
	end

	local finalObservations = observeAll()
	local finalResults = Plan.classifyAll(ops, finalObservations)
	local after = Plan.decide(MODE, ops, finalResults, gate)
	fill(finalResults, finalObservations, after.states)
	report.ok = ok
	if not ok then
		report.next = "Failed. Run AUDIT before anything else."
	elseif after.transaction ~= "" then
		report.next = "Wrote the " .. decision.transaction .. " transaction. Run AUDIT, then " .. MODE .. " again for the " .. after.transaction .. " transaction."
	else
		report.next = "Complete: every op is " .. want .. "."
	end
	return report
end
-- selftest_body.lua: the cases of selftest.lua (build.py --selftest puts CASES, hash.lua, plan.lua and engine.lua
-- above this). Everything runs against Instance.new trees that are never parented to the DataModel, with a fake
-- root resolver and fake files. The only service used is HttpService, for JSON.
local HttpService = game:GetService("HttpService")
local summary = { passed = 0, failed = 0, skipped = 0, cases = {} }
local function case(name, fn)
	local ok, result = pcall(fn)
	local status, detail = "passed", ""
	if not ok then
		status, detail = "failed", tostring(result)
	elseif result == "skipped" then
		status = "skipped"
	end
	summary[status] += 1
	table.insert(summary.cases, { name = name, status = status, detail = detail })
end
local function expect(condition, message)
	if not condition then
		error(message, 0)
	end
end
local function same(a, b)
	if type(a) ~= type(b) then
		return false
	end
	if type(a) ~= "table" then
		return a == b
	end
	for key, value in pairs(a) do
		if not same(value, b[key]) then
			return false
		end
	end
	for key in pairs(b) do
		if a[key] == nil then
			return false
		end
	end
	return true
end

local BEFORE = "return { version = 1 }\n"
local MIDDLE = "return { version = 1.5 }\n"
local AFTER = "return { version = 2 }\n"
local BEFORE2 = "return { second = 1 }\n"
local AFTER2 = "return { second = 2 }\n"
local PROBE_OLD = "return { probe = false }\n"
local PROBE = "return { probe = true }\n"
local BROKEN = "return {{{\n"
local MARK = "UIRestyleInstall"
local UI = { "ReplicatedStorage", "Modules", "Game", "UI" }
local PULSE = { "ReplicatedStorage", "Modules", "Game", "UIPulse" }

local function make(class, name, parent)
	local node = Instance.new(class)
	node.Name = name
	node.Parent = parent
	return node
end
-- A detached copy of the parts of the place the engine reads. Nothing here is parented to game.
local function newWorld()
	local world = {}
	world.RS = make("Folder", "ReplicatedStorage", nil)
	local config = make("Folder", "Config", world.RS)
	world.onboarding = make("Folder", "Onboarding", make("Folder", "Player", config))
	world.onboarding:SetAttribute("StudioVehicleSandboxEveryPlay", false)
	world.ui = make("Folder", "UI", config)
	world.ui:SetAttribute("Tint", Color3.new(0.5, 0.25, 1))
	world.label = make("StringValue", "Label", world.ui)
	world.label.Value = "a"
	world.gameFolder = make("Folder", "Game", make("Folder", "Modules", world.RS))
	world.modules = make("Folder", "UI", world.gameFolder)
	world.existing = make("ModuleScript", "Existing", world.modules)
	world.existing.Source = BEFORE
	world.second = make("ModuleScript", "Second", world.modules)
	world.second.Source = BEFORE2
	return world
end
local function newFiles()
	return {
		["t/after/Probe.lua"] = PROBE,
		["t/before/Existing.lua"] = BEFORE, ["t/after/Existing.lua"] = AFTER,
		["t/before/Second.lua"] = BEFORE2, ["t/after/Second.lua"] = AFTER2,
	}
end
local function newData()
	local fp = Hash.fingerprint
	return {
		phase = "selftest", placeId = 1, base = "t/", markAttribute = MARK, installable = true,
		ops = {
			{ id = "kit", kind = "create", transaction = "hierarchy", class = "Folder", path = PULSE, mark = "selftest:kit", attributes = { Note = "made by selftest", Scale = 1.5 } },
			{ id = "style", kind = "attribute", transaction = "hierarchy", path = { "ReplicatedStorage", "Config", "UI" }, key = "Style", after = "Pulse", was = { "Draft" } },
			{ id = "tint", kind = "attribute", transaction = "hierarchy", path = { "ReplicatedStorage", "Config", "UI" }, key = "Tint", before = { Type = "Color3", R = 0.5, G = 0.25, B = 1 }, after = { Type = "Color3", R = 0, G = 0.5, B = 1 } },
			{ id = "label", kind = "property", transaction = "hierarchy", path = { "ReplicatedStorage", "Config", "UI", "Label" }, key = "Value", before = "a", after = "b" },
			{ id = "probe", kind = "create", transaction = "hierarchy", class = "ModuleScript", path = { "ReplicatedStorage", "Modules", "Game", "UIPulse", "Probe" }, mark = "selftest:probe", parentOp = "kit", after = fp(PROBE), prior = { fp(PROBE_OLD) }, file = { after = "after/Probe.lua" } },
			{ id = "existing", kind = "source", transaction = "sources", class = "ModuleScript", path = { "ReplicatedStorage", "Modules", "Game", "UI", "Existing" }, before = fp(BEFORE), after = fp(AFTER), prior = { fp(MIDDLE) }, file = { before = "before/Existing.lua", after = "after/Existing.lua" } },
			{ id = "second", kind = "source", transaction = "sources", class = "ModuleScript", path = { "ReplicatedStorage", "Modules", "Game", "UI", "Second" }, before = fp(BEFORE2), after = fp(AFTER2), prior = {}, file = { before = "before/Second.lua", after = "after/Second.lua" } },
		},
	}
end
-- One engine run. options: files, data, placeId, isEdit, setSource. -> report, counters
local function run(mode, world, options)
	options = options or {}
	local files = options.files or newFiles()
	local counters = { fetches = 0, waits = 0, waypoints = 0, writes = 0 }
	local env = {
		placeId = options.placeId or 1,
		isEdit = options.isEdit ~= false,
		root = function(name)
			if name == "ReplicatedStorage" then
				return world.RS
			end
			return nil
		end,
		fetch = function(file)
			counters.fetches += 1
			local text = files[file]
			if text == nil then
				error("no such file " .. file)
			end
			return text
		end,
		loadChunk = Engine.loadChunk,
		getSource = function(node)
			return node.Source
		end,
		setSource = function(node, text)
			counters.writes += 1
			if options.setSource then
				options.setSource(node, text, counters.writes)
			else
				node.Source = text
			end
		end,
		wait = function()
			counters.waits += 1
		end,
		waypoint = function()
			counters.waypoints += 1
		end,
		jsonDecode = function(text)
			return HttpService:JSONDecode(text)
		end,
	}
	return Engine.run(mode, options.data or newData(), env), counters
end
local function opRow(report, id)
	for _, name in ipairs(Plan.TRANSACTIONS) do
		for _, row in ipairs(report.transactions[name].ops) do
			if row.id == id then
				return row
			end
		end
	end
	error("no row for " .. id, 0)
end
local function pulse(world)
	return world.gameFolder:FindFirstChild("UIPulse")
end
-- Runs APPLY twice (hierarchy, then sources) and checks both worked.
local function install(world)
	local first = run("APPLY", world)
	expect(first.ok and first.transaction == "hierarchy", "first APPLY: " .. table.concat(first.blockers, " | "))
	local second = run("APPLY", world)
	expect(second.ok and second.transaction == "sources", "second APPLY: " .. table.concat(second.blockers, " | "))
end
local function untouched(world)
	return pulse(world) == nil and world.ui:GetAttribute("Style") == nil and world.ui:GetAttribute("Tint") == Color3.new(0.5, 0.25, 1)
		and world.label.Value == "a" and world.existing.Source == BEFORE and world.second.Source == BEFORE2
end
local canCompile = Engine.loadChunk("return 1", "probe") ~= nil

case("hash.lua matches plan.py fingerprints", function()
	for index, vector in ipairs(CASES.hashes) do
		local got = Hash.fingerprint(vector.text)
		expect(got == vector.fp, "hash vector " .. index .. ": " .. got .. " is not " .. vector.fp)
	end
end)

case("plan.lua matches plan.py on every decision vector", function()
	local order = {}
	for index, op in ipairs(CASES.ops) do
		order[index] = op.id
	end
	for _, v in ipairs(CASES.cases) do
		local ops = CASES.ops
		if v.x then
			ops = CASES.mixedOps
		end
		local observations = {}
		for id, variant in pairs(v.w) do
			observations[id] = CASES.variants[id][variant]
		end
		local results = Plan.classifyAll(ops, observations)
		for index, id in ipairs(order) do
			local want, got = v.r[index], results[id]
			expect(got.state == want[1] and got.reason == want[2] and got.rollback == want[3],
				v.n .. ": " .. id .. " gave " .. got.state .. " / " .. got.reason .. " / " .. got.rollback)
		end
		local decision = Plan.decide(v.m, ops, results, CASES.gates[v.g])
		expect(same(decision.blockers, v.b), v.n .. ": blockers differ: " .. table.concat(decision.blockers, " | "))
		expect(decision.states.hierarchy == v.s[1] and decision.states.sources == v.s[2], v.n .. ": transaction states differ")
		expect(decision.transaction == v.t, v.n .. ": transaction is " .. decision.transaction)
		expect(decision.write == v.ok, v.n .. ": write flag differs")
		expect(#decision.actions == #v.a, v.n .. ": action count differs")
		for index, action in ipairs(decision.actions) do
			expect(action.id == v.a[index][1] and action.action == v.a[index][2], v.n .. ": action " .. index .. " differs")
		end
	end
end)

case("AUDIT on the before state writes nothing and reports each transaction", function()
	local world = newWorld()
	local report, counters = run("AUDIT", world)
	expect(report.ok, "blocked: " .. table.concat(report.blockers, " | "))
	expect(report.transactions.hierarchy.state == "before" and report.transactions.sources.state == "before", "transaction states")
	expect(#report.transactions.hierarchy.ops == 5 and #report.transactions.sources.ops == 2, "op rows")
	expect(report.apply.transaction == "hierarchy" and report.apply.ops == 5, "apply preview")
	expect(report.rollback.transaction == "" and report.rollback.ops == 0, "rollback preview")
	expect(counters.writes == 0 and counters.waypoints == 0 and untouched(world), "AUDIT wrote something")
	expect(opRow(report, "existing").served == (canCompile and "ok" or "unchecked"), "served status " .. opRow(report, "existing").served)
end)

case("APPLY writes the hierarchy transaction only", function()
	local world = newWorld()
	local report, counters = run("APPLY", world)
	expect(report.ok and report.transaction == "hierarchy" and report.wrote == 5, "report: " .. table.concat(report.blockers, " | "))
	local kit = pulse(world)
	expect(kit ~= nil and kit.ClassName == "Folder" and kit:GetAttribute(MARK) == "selftest:kit", "kit folder")
	expect(kit:GetAttribute("Note") == "made by selftest" and kit:GetAttribute("Scale") == 1.5, "kit attributes")
	local probe = kit:FindFirstChild("Probe")
	expect(probe ~= nil and probe.ClassName == "ModuleScript" and probe.Source == PROBE and probe:GetAttribute(MARK) == "selftest:probe", "probe module")
	expect(world.ui:GetAttribute("Style") == "Pulse" and world.ui:GetAttribute("Tint") == Color3.new(0, 0.5, 1) and world.label.Value == "b", "config values")
	expect(world.existing.Source == BEFORE and world.second.Source == BEFORE2, "a source was written in the hierarchy run")
	expect(report.transactions.hierarchy.state == "after" and report.transactions.sources.state == "before", "states after the run")
	expect(counters.waypoints == 2, "waypoints " .. counters.waypoints)
end)

case("second APPLY writes sources, third writes nothing", function()
	local world = newWorld()
	install(world)
	expect(world.existing.Source == AFTER and world.second.Source == AFTER2, "sources not written")
	local third, counters = run("APPLY", world)
	expect(third.ok and third.wrote == 0 and counters.writes == 0 and counters.waypoints == 0, "third APPLY wrote")
	local audit = run("AUDIT", world)
	expect(audit.ok and audit.transactions.hierarchy.state == "after" and audit.transactions.sources.state == "after", "AUDIT after install")
	expect(audit.apply.transaction == "" and audit.rollback.transaction == "sources", "previews after install")
end)

case("the engine waits between source writes", function()
	local world = newWorld()
	run("APPLY", world)
	local _, counters = run("APPLY", world)
	expect(counters.waits == 2, "waits " .. counters.waits)
end)

case("ROLLBACK undoes sources first, then the hierarchy", function()
	local world = newWorld()
	install(world)
	local kit = pulse(world)
	local first = run("ROLLBACK", world)
	expect(first.ok and first.transaction == "sources" and first.wrote == 2, "first ROLLBACK: " .. table.concat(first.blockers, " | "))
	expect(world.existing.Source == BEFORE and world.second.Source == BEFORE2 and pulse(world) == kit, "first ROLLBACK state")
	local second = run("ROLLBACK", world)
	expect(second.ok and second.transaction == "hierarchy" and second.wrote == 5, "second ROLLBACK: " .. table.concat(second.blockers, " | "))
	expect(untouched(world), "place is not back to the before state")
	expect(kit.Parent == nil, "created folder still parented")
	local third = run("ROLLBACK", world)
	expect(third.ok and third.wrote == 0, "third ROLLBACK wrote")
	install(world)
	expect(pulse(world) ~= nil and world.existing.Source == AFTER, "APPLY after ROLLBACK")
end)

case("an unknown source hash blocks the whole run", function()
	local world = newWorld()
	world.second.Source = "return 'edited by hand'\n"
	local audit = run("AUDIT", world)
	expect(not audit.ok and opRow(audit, "second").state == "BLOCKED", "AUDIT did not block")
	expect(audit.transactions.sources.state == "blocked" and audit.transactions.hierarchy.state == "before", "transaction states")
	local report, counters = run("APPLY", world)
	expect(not report.ok and report.wrote == 0 and counters.writes == 0, "APPLY wrote")
	expect(pulse(world) == nil and world.ui:GetAttribute("Style") == nil, "hierarchy written although a source is unknown")
end)

case("a prior source hash is accepted and rewritten", function()
	local world = newWorld()
	world.existing.Source = MIDDLE
	local audit = run("AUDIT", world)
	expect(audit.ok and opRow(audit, "existing").state == "prior", "AUDIT state " .. opRow(audit, "existing").state)
	install(world)
	expect(world.existing.Source == AFTER, "prior source not replaced")
end)

case("a prior created module is rewritten in the hierarchy run", function()
	local world = newWorld()
	install(world)
	pulse(world).Probe.Source = PROBE_OLD
	local report = run("APPLY", world)
	expect(report.ok and report.transaction == "hierarchy" and report.wrote == 1 and pulse(world).Probe.Source == PROBE, "probe not rewritten")
end)

case("an instance without the install mark blocks create", function()
	local world = newWorld()
	make("Folder", "UIPulse", world.gameFolder)
	local report = run("APPLY", world)
	expect(not report.ok and opRow(report, "kit").state == "BLOCKED" and report.wrote == 0, "unmarked folder accepted")
	expect(world.ui:GetAttribute("Style") == nil, "attribute written although create is blocked")
end)

case("an edited created module blocks APPLY and ROLLBACK", function()
	local world = newWorld()
	install(world)
	pulse(world).Probe.Source = "return 'tuned'\n"
	local apply = run("APPLY", world)
	local rollback, counters = run("ROLLBACK", world)
	expect(not apply.ok and not rollback.ok and counters.writes == 0, "edited module not blocked")
	expect(world.existing.Source == AFTER, "ROLLBACK wrote a source although the run was blocked")
end)

case("ROLLBACK refuses when a created instance has children it did not create", function()
	local world = newWorld()
	install(world)
	make("Folder", "Stray", pulse(world))
	local audit = run("AUDIT", world)
	expect(audit.ok and opRow(audit, "kit").rollback:find("Stray", 1, true) ~= nil, "AUDIT does not name the child")
	-- The sources transaction removes nothing, so the stray child does not stop it; the hierarchy one is refused.
	local first = run("ROLLBACK", world)
	expect(first.ok and first.transaction == "sources" and pulse(world) ~= nil, "sources ROLLBACK was refused")
	local report, counters = run("ROLLBACK", world)
	expect(not report.ok and report.wrote == 0 and counters.writes == 0, "hierarchy ROLLBACK ran")
	expect(pulse(world) ~= nil, "the created folder was removed")
end)

case("ROLLBACK refuses when an attribute was edited since", function()
	local world = newWorld()
	install(world)
	world.ui:SetAttribute("Style", "SomethingElse")
	local report = run("ROLLBACK", world)
	expect(not report.ok and opRow(report, "style").state == "BLOCKED" and world.existing.Source == AFTER, "edited attribute not refused")
end)

case("an earlier value of this delivery (was) is replaced by APPLY", function()
	local world = newWorld()
	world.ui:SetAttribute("Style", "Draft")
	local audit = run("AUDIT", world)
	expect(opRow(audit, "style").state == "prior", "state " .. opRow(audit, "style").state)
	local report = run("APPLY", world)
	expect(report.ok and world.ui:GetAttribute("Style") == "Pulse", "was value not replaced")
end)

case("a served source that does not match its hash blocks before any write", function()
	local world = newWorld()
	local files = newFiles()
	files["t/after/Probe.lua"] = PROBE .. "-- changed on disk\n"
	local audit = run("AUDIT", world, { files = files })
	expect(not audit.ok and opRow(audit, "probe").served == "mismatch", "AUDIT served status")
	local report, counters = run("APPLY", world, { files = files })
	expect(not report.ok and counters.writes == 0 and untouched(world), "APPLY wrote")
end)

case("a source that cannot be fetched blocks APPLY and only warns in AUDIT", function()
	local world = newWorld()
	local files = newFiles()
	files["t/after/Probe.lua"] = nil
	local audit = run("AUDIT", world, { files = files })
	expect(audit.ok and #audit.warnings > 0 and opRow(audit, "probe").served == "unavailable", "AUDIT")
	local report = run("APPLY", world, { files = files })
	expect(not report.ok and untouched(world), "APPLY wrote")
end)

case("an after-source with a syntax error blocks (needs loadstring)", function()
	if not canCompile then
		return "skipped"
	end
	local world = newWorld()
	run("APPLY", world)
	local files = newFiles()
	files["t/after/Second.lua"] = BROKEN
	local data = newData()
	data.ops[7].after = Hash.fingerprint(BROKEN)
	local report, counters = run("APPLY", world, { files = files, data = data })
	expect(not report.ok and counters.writes == 0 and world.existing.Source == BEFORE, "syntax error not blocked")
end)

case("a failure while writing sources restores the sources already written", function()
	local world = newWorld()
	run("APPLY", world)
	local report = run("APPLY", world, { setSource = function(node, text, call)
		if call == 2 then
			error("injected failure")
		end
		node.Source = text
	end })
	expect(not report.ok and report.restored == true and report.wrote == 0, "report")
	expect(world.existing.Source == BEFORE and world.second.Source == BEFORE2, "sources not restored")
	expect(report.transactions.sources.state == "before", "state after recovery")
end)

case("a failure while writing the hierarchy removes created instances and restores values", function()
	local world = newWorld()
	local report = run("APPLY", world, { setSource = function()
		error("injected failure")
	end })
	expect(not report.ok and report.restored == true, "report")
	expect(untouched(world), "hierarchy not restored")
end)

case("a write that does not take effect fails the post-write check and is undone", function()
	local world = newWorld()
	run("APPLY", world)
	local report = run("APPLY", world, { setSource = function(node, text, call)
		if call ~= 2 then
			node.Source = text
		end
	end })
	expect(not report.ok and world.existing.Source == BEFORE and world.second.Source == BEFORE2, "silent write accepted")
end)

case("APPLY refuses while the sandbox test window is open", function()
	local world = newWorld()
	world.onboarding:SetAttribute("StudioVehicleSandboxEveryPlay", true)
	local audit = run("AUDIT", world)
	expect(audit.ok and #audit.warnings > 0 and #audit.apply.blockers == 1, "AUDIT does not warn")
	local report = run("APPLY", world)
	expect(not report.ok and untouched(world), "APPLY ran with the sandbox on")
	world.onboarding:SetAttribute("StudioVehicleSandboxEveryPlay", false)
	world.onboarding:SetAttribute("UIRestyleTestWindow", "open")
	report = run("APPLY", world)
	expect(not report.ok and untouched(world), "APPLY ran with the marker set")
	world.onboarding.Parent = nil
	report = run("APPLY", world)
	expect(not report.ok and untouched(world), "APPLY ran although the window cannot be checked")
end)

case("ROLLBACK is allowed while the test window is open", function()
	local world = newWorld()
	install(world)
	world.onboarding:SetAttribute("UIRestyleTestWindow", "open")
